<?php use Pjas\Http\{Csrf,View};use Pjas\Support\Labels; ?>
<h1>利用者と操作できるサイト</h1><p class="sub">利用者ごとに、見るだけ・公開できる・全体を管理できる権限を設定します。</p>
<div class="card"><table><thead><tr><th>利用者</th><th>権限</th><th>ログイン</th><th></th></tr></thead><tbody><?php foreach($users as $u):?><tr><td><?= View::e($u['email']) ?></td><td><?= View::e(Labels::role($u['role'])) ?><br><small class="muted"><?= $u['scope_all']?'すべてのサイト':'選択したサイトのみ' ?></small></td><td><?= $u['enabled']?'有効':'停止中' ?> · <?= $u['has_totp']?'二段階認証あり':'二段階認証なし' ?></td><td><a class="btn sm" href="/users?id=<?= $u['id'] ?>">編集</a></td></tr><?php endforeach;?></tbody></table></div>
<div class="card" style="margin-top:18px"><div class="card-h"><?= $edit?'利用者を編集する':'利用者を追加する' ?></div><div class="card-b"><form method="post" action="/users"><?= Csrf::field() ?><input type="hidden" name="id" value="<?= (int)($edit['id']??0) ?>">
<div class="field"><label>メールアドレス</label><input type="email" name="email" value="<?= View::e($edit['email']??'') ?>" required></div><div class="field"><label><?= $edit?'変更する場合の新しいパスワード':'初期パスワード' ?></label><input type="password" name="new_password" autocomplete="new-password" minlength="12" <?= $edit?'':'required' ?>><div class="hint">12文字以上。編集時は空欄にすると現在のパスワードを維持します。</div></div>
<div class="field"><label>基本の権限</label><select name="role"><?php foreach(['viewer','operator','owner'] as $role):?><option value="<?= $role ?>" <?= ($edit['role']??'viewer')===$role?'selected':'' ?>><?= View::e(Labels::role($role)) ?></option><?php endforeach;?></select></div>
<label class="inline"><input type="checkbox" name="enabled" <?= !$edit||$edit['enabled']?'checked':'' ?>>ログインを許可する</label><label class="inline"><input type="checkbox" name="scope_all" <?= !empty($edit['scope_all'])?'checked':'' ?>>すべてのサイトを操作できる（今後登録するサイトも含む）</label><p class="hint">全体の管理者は常にすべてのサイトを操作できます。見るだけの基本権限を選んだ利用者には、公開操作を許可しません。</p>
<?php foreach($services as $s):?><div class="field"><label><?= View::e($s['name']) ?></label><select name="sites[<?= $s['id'] ?>]"><?php foreach([''=>'操作させない','viewer'=>'見るだけ','operator'=>'公開・ロールバックもできる'] as $value=>$label):?><option value="<?= $value ?>" <?= ($grants[$s['id']]??'')===$value?'selected':'' ?>><?= $label ?></option><?php endforeach;?></select></div><?php endforeach;?>
<div class="field"><label>確認用の現在のパスワード（ログイン直後は省略できます）</label><input type="password" name="confirm_password" autocomplete="current-password"></div><button class="btn p">利用者と権限を保存する</button><?php if($edit):?> <a class="btn" href="/users">新しく追加する</a><?php endif;?></form></div></div>
